  <?php if($isV1): ?><section class="v1-demo" id="v1-demo" aria-labelledby="v1-title"><div class="v1-demo-head"><div><span class="bos-kicker">FIRST PLAYABLE BUILD · V1</span><h2 id="v1-title">Try the core loop</h2><p id="v1-instruction">Loading the game loop…</p></div><div class="v1-score"><small>SCORE</small><b id="v1-score-value">0</b></div></div><div class="v1-arena" id="v1-arena"><div class="v1-start" id="v1-start"><span><?=e((string)$game['icon'])?></span><strong>Ready when you are</strong><button class="bos-btn" type="button">Start demo</button></div><button class="v1-target" id="v1-target" type="button" aria-label="Game target"></button></div><div class="v1-controls"><span id="v1-timer">30s</span><span id="v1-status">A short playable proof of the game’s main interaction.</span><button class="bos-btn secondary" id="v1-reset" type="button">Reset</button></div></section><?php endif; ?>
