<?php if($isV1): ?><script>
const v1=document.getElementById('v1-demo'),arena=document.getElementById('v1-arena'),start=document.getElementById('v1-start'),target=document.getElementById('v1-target'),scoreEl=document.getElementById('v1-score-value'),timerEl=document.getElementById('v1-timer'),statusEl=document.getElementById('v1-status'),instruction=document.getElementById('v1-instruction'),reset=document.getElementById('v1-reset');
const category=document.querySelector('.detail-main').dataset.gameCategory.toLowerCase();let score=0,time=30,playing=false,clock=null,mode=category.includes('sports')?'timing':category.includes('creative')?'sequence':category.includes('learning')?'knowledge':category.includes('casual')?'merge':'action';
const copy={action:'Move fast: tap the glowing target before it jumps.',timing:'Time your release inside the gold zone to build a streak.',sequence:'Complete the pattern by tapping the highlighted tiles in order.',knowledge:'Answer the quick prompt to earn points for your next move.',merge:'Tap matching cores to merge them into a higher-value bit.'}; instruction.textContent=copy[mode];
function place(){target.style.left=(8+Math.random()*78)+'%';target.style.top=(18+Math.random()*65)+'%';target.dataset.value=mode==='knowledge'?'1':'0';target.textContent=mode==='knowledge'?(Math.random()>.5?'✓':'✕'):mode==='sequence'?'◆':mode==='merge'?'◉':'+';target.className='v1-target '+mode;}
function finish(){playing=false;clearInterval(clock);target.hidden=true;statusEl.textContent='Run complete — '+score+' points. Play again to beat your score.';start.hidden=false;start.querySelector('strong').textContent='Demo complete';start.querySelector('button').textContent='Play again';}
function begin(){score=0;time=30;playing=true;start.hidden=true;target.hidden=false;scoreEl.textContent=score;statusEl.textContent='Go!';place();clearInterval(clock);clock=setInterval(()=>{time--;timerEl.textContent=time+'s';if(time<=0)finish()},1000)}
start.querySelector('button').onclick=begin;target.onclick=()=>{if(!playing)return;score+=mode==='knowledge'&&target.dataset.value==='0'?-2:mode==='timing'?15:10;score=Math.max(0,score);scoreEl.textContent=score;statusEl.textContent=score%50===0?'Combo boost!':'Nice move!';place()};reset.onclick=()=>{clearInterval(clock);playing=false;score=0;time=30;scoreEl.textContent=0;timerEl.textContent='30s';statusEl.textContent='A short playable proof of the game’s main interaction.';start.hidden=false;target.hidden=true};target.hidden=true;
</script><?php endif; ?>
<script>
const follow=document.getElementById('followGame'),note=document.getElementById('followNote');if(follow){const key='beyond-games-following',slug=follow.dataset.slug;let list=JSON.parse(localStorage.getItem(key)||'[]');const sync=()=>{const active=list.includes(slug);follow.textContent=active?'Following development ✓':'Follow development';note.textContent=active?'Saved locally. This title is now on your development watchlist.':''};follow.addEventListener('click',()=>{list=list.includes(slug)?list.filter(x=>x!==slug):[...list,slug];localStorage.setItem(key,JSON.stringify(list));sync()});sync()}
</script>
